<?php require __DIR__.'/../includes/bootstrap.php'; if(is_admin()){header('Location:index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf())$error='Phiên làm việc không hợp lệ.';else{$s=db()->prepare('SELECT id,username,password,email,role FROM users WHERE username=? LIMIT 1');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u && password_verify($_POST['password']??'',$u['password'])){unset($u['password']);session_regenerate_id(true);$_SESSION['user']=$u;header('Location:index.php');exit;}$error='Tên đăng nhập hoặc mật khẩu không đúng.';}} ?>
